package com.bank.seniority;

import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.logging.*;

public class DaysBetweenDemo {
    private static final Logger log = Logger.getLogger("Seniority");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        Employee rajesh = new Employee("Rajesh", LocalDate.parse("2020-01-01"));
        Employee priya = new Employee("Priya", LocalDate.parse("2020-03-01"));
        SeniorityService service = new SeniorityService();

        long signed = service.daysBetweenJoining(rajesh, priya);
        long absGap = service.absoluteDaysBetween(rajesh, priya);
        log.info(() -> "Signed (Rajesh → Priya): " + signed + " days");
        log.info(() -> "Absolute gap           : " + absGap + " days");
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    private final LocalDate joinDate;
    Employee(String name, LocalDate joinDate) { this.name = name; this.joinDate = joinDate; }
    String getName() { return name; }
    LocalDate getJoinDate() { return joinDate; }
}

// ─── Would be in service/SeniorityService.java ───
class SeniorityService {
    long daysBetweenJoining(Employee a, Employee b) {
        return ChronoUnit.DAYS.between(a.getJoinDate(), b.getJoinDate()); // signed
    }
    long absoluteDaysBetween(Employee a, Employee b) {
        return Math.abs(daysBetweenJoining(a, b));                        // order-independent
    }
}
